                    _ = try stmts.inside_wrapper_prefix.appendNonDependency(Stmt.alloc(S.Local, .{ .kind = .k_var, .decls = try G.Decl.List.fromSlice(allocator, (&.{ G.Decl{ .binding = Binding.alloc(allocator, B.Identifier{ .ref = st.namespace_ref }, ((st.star_name_loc) orelse (stmt.loc))), .value = call } })) }, stmt.loc));
                }
            } else {
                const loc = ((st.star_name_loc) orelse (stmt.loc));
                if (is_bare_import) {
                    _ = try esm_decls.append(allocator, .{ .binding = .{ .data = .b_missing, .loc = .Empty } });
                    _ = try esm_callbacks.append(allocator, Expr.init(E.Arrow, .noop_return_undefined, .Empty));
                } else {
                    const binding = Binding.alloc(allocator, B.Identifier{ .ref = st.namespace_ref }, loc);
                    _ = try esm_decls.append(allocator, .{ .binding = binding });
                    _ = try esm_callbacks.append(allocator, Expr.init(E.Arrow, .{ .args = try allocator.dupe(G.Arg, (&.{ G.Arg{ .binding = Binding.alloc(allocator, B.Identifier{ .ref = ast.module_ref }, .Empty) } })), .prefer_expr = true, .body = try G.FnBody.initReturnExpr(allocator, Expr.init(E.Binary, .{ .op = .bin_assign, .left = Expr.initIdentifier(st.namespace_ref, .Empty), .right = Expr.initIdentifier(ast.module_ref, .Empty) }, .Empty)) }, .Empty));
                }
                _ = try stmts.append(.outside_wrapper_prefix, stmt);
            }
},
else => {
_ = try stmts.append(.inside_wrapper_suffix, stmt);
},
}
        }
        if ((esm_decls.items.len > 0)) {
            _ = try stmts.inside_wrapper_prefix.appendNonDependency(Stmt.alloc(S.Local, .{ .kind = .k_var, .decls = try G.Decl.List.fromSlice(allocator, (&.{ G.Decl{ .binding = Binding.alloc(allocator, B.Array{ .items = esm_decls.items, .is_single_line = true }, .Empty), .value = Expr.init(E.Dot, .{ .target = hmr_api_id, .name = "imports", .name_loc = .Empty }, .Empty) } })) }, .Empty));
            _ = try stmts.inside_wrapper_prefix.appendNonDependency(Stmt.alloc(S.SExpr, .{ .value = Expr.init(E.Binary, .{ .op = .bin_assign, .left = Expr.init(E.Dot, .{ .target = hmr_api_id, .name = "updateImport", .name_loc = .Empty }, .Empty), .right = Expr.init(E.Array, .{ .items = .moveFromList((&esm_callbacks)), .is_single_line = (esm_callbacks.items.len <= 2) }, .Empty) }, .Empty) }, .Empty));
        }
}
